/** @purity pure */
export function isMissingKeyFault(one: JsonFault): boolean {
  return one.what === A_KEY_THIS_SHAPE_LACKS
}

/** @purity pure */
function pointer(at: string, key: string): string {
  return `${at}/${key.replace(/~/g, '~0').replace(/\//g, '~1')}`
}

/** @purity pure */
function jsonTypeHolds(value: unknown, kind: JsonSchemaKind): boolean {
  switch (kind) {
    case 'null':
      return value === null
    case 'boolean':
      return typeof value === 'boolean'
    case 'integer':
      return typeof value === 'number' && Number.isInteger(value)
    case 'number':
      return typeof value === 'number' && Number.isFinite(value)
    case 'string':
      return typeof value === 'string'
    case 'array':
      return Array.isArray(value)
    case 'object':
      return isObject(value)
    default: {
      const unreached: never = kind
      return unreached
    }
  }
}

/** @purity pure */
function jsonTypeOf(value: unknown): string {
  if (value === null) return 'null'
  if (Array.isArray(value)) return 'an array'
  if (typeof value === 'number') return Number.isInteger(value) ? 'an integer' : 'a number'
  if (typeof value === 'string') return 'a string'
  if (typeof value === 'boolean') return 'a boolean'
  if (isObject(value)) return 'an object'
  return typeof value
}

// see T-220, T-017b
/** @purity pure */
function stringFaults(value: string, node: SchemaNode, at: string, out: JsonFault[]): void {
  // TRAP: count code points, as JSON Schema maxLength does; value.length counts UTF-16 units.
  if (node.maxLength !== undefined && [...value].length > node.maxLength) {
    out.push(jsonFault(at, `is longer than the ${node.maxLength} characters allowed`))
  }
  if (node.pattern !== undefined && !new RegExp(node.pattern).test(value)) {
    out.push(jsonFault(at, 'is not spelled as the schema allows'))
  }
}

/** @purity pure */
function collectFaults(
  value: unknown,
  node: SchemaNode,
  at: string,
  out: JsonFault[],
): void {
  if (node.ref !== undefined) {
    const target = SCHEMA_DEFS[node.ref]
    if (target !== undefined) collectFaults(value, target, at, out)
    return
  }
  if (node.alternatives !== undefined) return alternativeFaults(value, node.alternatives, at, out)

  const kinds = node.type
  if (kinds !== undefined && !kinds.some((kind) => jsonTypeHolds(value, kind))) {
    out.push(jsonFault(at, `expected ${kinds.join(' or ')}, was ${jsonTypeOf(value)}`))
    return
  }

  const members = node.enum
  if (members !== undefined && !(members as readonly unknown[]).includes(value)) {
    out.push(
      jsonFault(at, `is not one of ${members.map((one) => JSON.stringify(one)).join(', ')}`),
    )
    return
  }

  if (typeof value === 'number') {
    if (node.minimum !== undefined && value < node.minimum) {
      out.push(jsonFault(at, `is below the least value allowed, ${node.minimum}`))
    }
    if (node.maximum !== undefined && value > node.maximum) {
      out.push(jsonFault(at, `is above the greatest value allowed, ${node.maximum}`))
    }
  }
  if (typeof value === 'string') stringFaults(value, node, at, out)

  if (isObject(value)) objectFaults(value, node, at, out)

  const items = node.items
  if (items !== undefined && Array.isArray(value)) {
    value.forEach((element, index) => collectFaults(element, items, `${at}/${index}`, out))
  }
}

/** @purity pure */
function objectFaults(value: Readonly<Record<string, unknown>>, node: SchemaNode, at: string, out: JsonFault[]): void {
  for (const key of node.required ?? []) {
    if (!(key in value)) out.push(jsonFault(pointer(at, key), A_KEY_THIS_SHAPE_LACKS))
  }
  for (const [key, inner] of Object.entries(value)) {
    const child = node.properties?.[key] ?? node.values
    if (child !== undefined) {
      collectFaults(inner, child, pointer(at, key), out)
    } else if (node.closed === true) {
      out.push(jsonFault(pointer(at, key), NOT_A_KEY_THIS_SHAPE_CARRIES))
    }
  }
}

// see T-108
// WHY: no alternative is nearer than another, so the faults of each are not told; only that none fits.
/** @purity pure */
function alternativeFaults(value: unknown, alternatives: readonly SchemaNode[], at: string, out: JsonFault[]): void {
  const fits = alternatives.some((one) => {
    const tried: JsonFault[] = []
    collectFaults(value, one, at, tried)
    return tried.length === 0
  })
  if (!fits) out.push(jsonFault(at, `fits none of the ${alternatives.length} shapes allowed`))
}

/** @purity pure */
export function collectSchemaFaults(value: unknown, out: JsonFault[]): void {
  collectFaults(value, GRS_DOCUMENT_SCHEMA, '', out)
}

// see T-108, FR-028, AG-9a
// WHY: a command handed to the Agent API is untyped; one refused here never reaches the planning that throws on it.
/** @purity pure */
export function commandShapeFaults(command: unknown): readonly JsonFault[] {
  const kind = isObject(command) ? command['kind'] : undefined
  const shape = typeof kind === 'string' && Object.hasOwn(SHAPE_OF_COMMAND_KIND, kind) ? SHAPE_OF_COMMAND_KIND[kind] : undefined
  if (shape === undefined) return [jsonFault('/kind', 'is not the kind of a command of table T-108')]
  const out: JsonFault[] = []
  collectFaults(command, shape, '', out)
  return out
}

// see FR-021, AT-154, AT-155
// WHY: held to the same $defs/Time a GRS JSON read holds the two columns to, so a value moved into a column
// from MSPDI always reads back from the GRS JSON written of it.
/** @purity pure */
export function isTimeText(text: string): boolean {
  const faults: JsonFault[] = []
  collectFaults(text, { ref: TIME_DEFINITION }, '', faults)
  return faults.length === 0
}

const TIME_DEFINITION = 'Time'

/** @purity pure */
export function collectionNamesOfEntity(entity: string): readonly string[] {
  const scheduleNode = GRS_DOCUMENT_SCHEMA.properties?.['schedule']
  const collections = scheduleNode?.properties ?? {}
  return Object.entries(collections)
    .filter(([, node]) => node.items?.ref === entity)
    .map(([name]) => name)
}
